// MEMS staff administration › Module lists › Skills master (HR).
// Database-backed skills catalogue (reference/skills_master): Category → Subcategory → Skill, codified
// HR_SK_ccc_nnn with a description and an enabled status.
//   Import          adds the default skills (INITIAL_SKILLS above) that are not in the database yet, 35 per request;
//                   existing records are never overwritten (the server skips them as well)
//   Enable/disable  per skill, from the sheet opened by tapping a row; always confirmed
// Organisations pick skills from the HRM metadata list (module_workspaces/HRM/metadata/skillsMaster), which is
// managed under Modules › HRM › Metadata (SkillsBrowser), not on this page.

interface Skill {
    code: string;
    category: string;
    subcategory: string;
    name: string;
    description: string;
    enabled: boolean;
}

interface Catalog {
    skills: Skill[];
    count: number;
}

/** Skills per import request (the server accepts 1–40). */
const IMPORT_BATCH = 35;

const COLUMNS: Array<Column<Skill>> = [
    { key: 'code', label: 'Code', value: (s) => s.code, className: 'font-mono text-xs' },
    { key: 'category', label: 'Category', value: (s) => s.category },
    { key: 'subcategory', label: 'Subcategory', value: (s) => s.subcategory },
    { key: 'name', label: 'Skill', value: (s) => s.name, className: 'font-semibold text-ink' },
    { key: 'description', label: 'Description', value: (s) => s.description, className: 'text-muted' },
    {
        key: 'status',
        label: 'Status',
        value: (s) => (s.enabled ? 'Enabled' : 'Disabled'),
        render: (s) => <Badge tone={s.enabled ? 'brand' : 'danger'}>{s.enabled ? 'Enabled' : 'Disabled'}</Badge>,
    },
];

const selectClass = 'h-11 min-w-0 flex-1 rounded-xl border border-line bg-panel px-3 text-base text-ink focus:border-brand focus:outline-none';

export default function SkillsMasterPage() {
    const { data, error, loading, reload } = useLoad(() => callBackend<Catalog>('/api/admin/skills/list'));
    const [category, setCategory] = useState('');
    const [subcategory, setSubcategory] = useState('');
    const [selectedCode, setSelectedCode] = useState('');
    const [message, setMessage] = useState('');
    const confirm = useConfirm();

    const skills = useMemo(() => data?.skills ?? [], [data]);
    const categories = useMemo(() => [...new Set(skills.map((s) => s.category))].sort(), [skills]);
    const subcategories = useMemo(() => [...new Set(skills.filter((s) => !category || s.category === category).map((s) => s.subcategory))].sort(), [skills, category]);
    const subcategoryCount = useMemo(() => new Set(skills.map((s) => s.subcategory)).size, [skills]);
    const rows = useMemo(() => skills.filter((s) => (!category || s.category === category) && (!subcategory || s.subcategory === subcategory)), [skills, category, subcategory]);
    const missing = useMemo(() => {
        const have = new Set(skills.map((s) => s.code));
        return INITIAL_SKILLS.filter((s) => !have.has(s.code));
    }, [skills]);
    const selected = skills.find((s) => s.code === selectedCode) ?? null;

    const importDefaults = () => {
        const pending = missing;
        const batches = Math.ceil(pending.length / IMPORT_BATCH);
        confirm.ask(
            {
                title: skills.length ? 'Import missing default skills?' : 'Initialise the skills database?',
                message: (
                    <div className='space-y-2'>
                        <p>
                            {pending.length} of {INITIAL_SKILLS.length} default skills are not in the catalogue yet. They are added in {batches} {batches === 1 ? 'batch' : 'batches'}.
                        </p>
                        <p>Existing records are preserved: nothing is overwritten or removed.</p>
                    </div>
                ),
                confirmLabel: `Import ${pending.length} skills`,
            },
            async () => {
                setMessage('');
                let total = 0;
                try {
                    for (let i = 0; i < pending.length; i += IMPORT_BATCH) {
                        const res = await callBackend<{ inserted: number }>('/api/admin/skills/import', { skills: pending.slice(i, i + IMPORT_BATCH) });
                        total += res.inserted;
                    }
                } catch (err) {
                    reload();
                    throw new Error(total ? `${total} skills were added before the import stopped. ${messageOf(err)}` : messageOf(err));
                }
                setMessage(`${total} skills added to the database. Existing records preserved.`);
                reload();
            },
        );
    };

    const toggle = (s: Skill) => {
        const disabling = s.enabled;
        confirm.ask(
            {
                title: disabling ? `Disable ${s.name}?` : `Enable ${s.name}?`,
                message: (
                    <p>
                        <span className='font-mono'>{s.code}</span> · {s.category} → {s.subcategory}.{' '}
                        {disabling ? 'The skill stays in the catalogue, marked disabled.' : 'The skill is marked enabled in the catalogue.'}
                    </p>
                ),
                confirmLabel: disabling ? 'Disable skill' : 'Enable skill',
                tone: disabling ? 'danger' : 'primary',
            },
            async () => {
                await callBackend('/api/admin/skills/update', { code: s.code, enabled: !s.enabled });
                setSelectedCode('');
                setMessage(`${s.name} ${disabling ? 'disabled' : 'enabled'}.`);
                reload();
            },
        );
    };

    const subtitle = data ? `${skills.length} skills · ${categories.length} categories · ${subcategoryCount} subcategories · ${missing.length} defaults missing` : undefined;

    return (
        <Screen
            title='Skills master'
            eyebrow='HRM · reference/skills_master'
            subtitle={subtitle}
            actions={
                <>
                    <Button variant='secondary' aria-label='Refresh' className='w-11 px-0' disabled={loading} onClick={reload}>
                        <RefreshCw className='h-4 w-4' />
                    </Button>
                    <Button disabled={!data || missing.length === 0} onClick={importDefaults}>
                        <Download className='h-4 w-4' />
                        {skills.length ? 'Import' : 'Initialise'}
                    </Button>
                </>
            }
            toolbar={
                <div className='flex items-start gap-2'>
                    <select
                        aria-label='Skill category'
                        className={selectClass}
                        value={category}
                        onChange={(e) => {
                            setCategory(e.target.value);
                            setSubcategory('');
                        }}
                    >
                        <option value=''>All categories</option>
                        {categories.map((c) => (
                            <option key={c} value={c}>
                                {c}
                            </option>
                        ))}
                    </select>
                    <select aria-label='Skill subcategory' className={selectClass} value={subcategory} onChange={(e) => setSubcategory(e.target.value)}>
                        <option value=''>All subcategories</option>
                        {subcategories.map((c) => (
                            <option key={c} value={c}>
                                {c}
                            </option>
                        ))}
                    </select>
                    <InfoTip label='About this catalogue'>
                        This page edits the MEMS reference catalogue (reference/skills_master). Import adds missing default skills only. The list organisations pick
                        skills from is managed under Modules › HRM › Metadata › Skills master.
                    </InfoTip>
                </div>
            }
        >
            {error && <Alert tone='error'>{error}</Alert>}
            {message && <Alert tone='success'>{message}</Alert>}
            {loading && !data ? (
                <Spinner />
            ) : (
                data && (
                    <RichTable
                        id='admin.skills.master'
                        title={category ? (subcategory ? `${category} › ${subcategory}` : category) : 'All skills'}
                        columns={COLUMNS}
                        rows={rows}
                        rowKey={(s) => s.code}
                        onRowClick={(s) => setSelectedCode(s.code)}
                        rowClassName={(s) => (s.enabled ? '' : 'opacity-60')}
                        fileName='skills-master'
                        height='h-[calc(100dvh-17rem)]'
                        empty={skills.length ? 'No skills in this category.' : 'The skills database is empty. Tap Initialise to import the default catalogue.'}
                    />
                )
            )}

            <DetailSheet
                open={!!selected}
                title={selected?.name ?? ''}
                eyebrow={selected?.code}
                onClose={() => setSelectedCode('')}
                footer={
                    selected && (
                        <>
                            <Button variant='secondary' className='flex-1' onClick={() => setSelectedCode('')}>
                                Close
                            </Button>
                            <Button variant={selected.enabled ? 'danger' : 'primary'} className='flex-1' onClick={() => toggle(selected)}>
                                <Power className='h-4 w-4' />
                                {selected.enabled ? 'Disable skill' : 'Enable skill'}
                            </Button>
                        </>
                    )
                }
            >
                {selected && (
                    <>
                        <p className='leading-relaxed text-ink'>{selected.description || 'No description configured.'}</p>
                        <div>
                            <DetailRow label='Category'>{selected.category}</DetailRow>
                            <DetailRow label='Subcategory'>{selected.subcategory}</DetailRow>
                            <DetailRow label='Status'>
                                <Badge tone={selected.enabled ? 'brand' : 'danger'}>{selected.enabled ? 'Enabled' : 'Disabled'}</Badge>
                            </DetailRow>
                        </div>
                    </>
                )}
            </DetailSheet>
            {confirm.sheet}
        </Screen>
    );
}